// The 28-byte MSG the pumps fill (hwnd, message, wParam, lParam, time, pt): the originals keep it in a 0x1c-byte frame slot.
struct c3fe_msg { unsigned hwnd, message, wParam, lParam, time, x, y; };

// fld qword + fst(p) qword: the 64 bits as x87 stores them back (a signaling NaN gets its quiet bit, bit 51). Kept as integers so
// no x87 return register (the x86 ABI returns a double in st(0)) touches the value.
uint64_t c3fe_x87load(const void* src) {
    uint64_t b = *static_cast<const uint64_t*>(src);
    if ((b & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (b & 0x000fffffffffffffull) && !(b & 0x0008000000000000ull))
        b |= 0x0008000000000000ull;
    return b;
}
void c3fe_x87move(void* dst, const void* src) { *static_cast<uint64_t*>(dst) = c3fe_x87load(src); }

// fcomp qword [0.0] then `test ah, 0x40` (C3): taken for equal AND for unordered (a NaN sets C0, C2 and C3).
bool c3fe_eqOrUnordered0(double x) {
    if (x == 0.0) return true;                                                // equal (also -0.0)
    if (x != x) return true;                                                  // unordered
    return false;
}

// The rate step shared by updateVoiceRate (0x10032526-0x10032581) and Channel_startVoice (0x100349c9-0x10034a2c): the engine's
// output rate R (engine vtable slot +0x40, zero-extended to 64 bits for fild qword) against the channel's base rate B (+0x1c0,
// the same). With B > R (fcom st(1), `test ah, 0x41` not taken): q = B / R (fdivrp), the step = __ftol(n / q) with n the signed
// dword at `nOff` (fild dword, fdiv st(1); __ftol 0x10042550 truncates through a 64-bit fistp and keeps the low dword), and the
// rate = D / q (fdivr qword at `dOff`). Otherwise the step is n unchanged and the rate D as loaded (fld qword). The step is
// stored at `stepOff`, the rate at `r1Off` (fst) and `r2Off` (fstp).
void c3fe_rateStep(char* v, unsigned R, unsigned B, int nOff, int dOff, int stepOff, int r1Off, int r2Off) {
    double dr = static_cast<double>(static_cast<unsigned long long>(R));
    double db = static_cast<double>(static_cast<unsigned long long>(B));
    if (db > dr) {
        double q = db / dr;
        double step = static_cast<double>(fat<int>(v, nOff)) / q;
        fat<unsigned>(v, stepOff) = static_cast<unsigned>(static_cast<long long>(step));
        double rate = fat<double>(v, dOff) / q;
        fat<double>(v, r1Off) = rate;
        fat<double>(v, r2Off) = rate;
    } else {
        fat<unsigned>(v, stepOff) = fat<unsigned>(v, nOff);
        uint64_t rate = c3fe_x87load(v + dOff);
        fat<uint64_t>(v, r1Off) = rate;
        fat<uint64_t>(v, r2Off) = rate;
    }
}

