// 0x0002a970  soundThreadPump (VA 0x1002a970). The start routine startSignalThread 0x1002a920 passes to _beginthread 0x10042984
// (`push 0x10001366` at 0x1002a939; thunk 0x10001366 -> 0x1002a970). __cdecl, `ret`. The running byte 0x100b5060 = 1
// (0x1002a973); GetCurrentThreadId (slot 0x100b8408) goes to 0x100b5054 (0x1002a97d / 0x1002a996). Then
// MsgWaitForMultipleObjects (slot 0x100b85a8) with (1, &event 0x100b505c, FALSE, INFINITE, QS_POSTMESSAGE|QS_SENDMESSAGE = 0x48)
// (0x1002a989-0x1002a99b): 0 (the event) ends the thread (0x1002a99f -> 0x1002aa34: running byte 0, eax 0). Each other result:
// EnterCriticalSection (slot 0x100b83f4) on 0x100b503c (0x1002a9b1 / 0x1002a9b6); bit 0 of the flag byte 0x100b5038 clear
// (0x1002a9bc / 0x1002a9c3) leaves through LeaveCriticalSection (slot 0x100b84e0) with the running byte 0 and LeaveCriticalSection's
// eax returned (0x1002aa2d-0x1002aa41); set: PeekMessageA (slot 0x100b85b4) with (&msg, 0, 0, 0, PM_REMOVE) in a loop
// (0x1002a9c5-0x1002a9d6 / 0x1002a9f4-0x1002aa05), each message to soundWindowProc (thunk 0x10001780 -> 0x100288a0, __cdecl) as
// (hwnd, message, wParam, lParam) (0x1002a9d8-0x1002a9f1); then LeaveCriticalSection (0x1002aa07 / 0x1002aa0c) and the next wait
// (0x1002aa0e-0x1002aa1b): non-zero repeats (0x1002aa1f), 0 stores its low byte as the running byte and returns it (0x1002aa21-
// 0x1002aa2c).
typedef unsigned(__cdecl* ThreadPump_t)();
ThreadPump_t ThreadPump_orig;
unsigned __cdecl ThreadPump_re() {
    c3fe_g<unsigned char>(kSigRunning) = 1;                                   // 0x1002a973
    c3fe_g<unsigned>(kSigTid) = c3fe_imp<Imp0_t>(kIatGetCurrentThreadId)();   // 0x1002a97d / 0x1002a996
    MsgWait_t wait = c3fe_imp<MsgWait_t>(kIatMsgWait);                        // 0x1002a983
    void* ev = c3fe_sound(kSigEvent);
    void* cs = c3fe_sound(kSigCS);
    unsigned r = wait(1, ev, 0, 0xffffffffu, 0x48);                           // 0x1002a989-0x1002a99b
    if (r == 0) {                                                             // 0x1002a99d / 0x1002a99f
        c3fe_g<unsigned char>(kSigRunning) = 0;                               // 0x1002aa36
        return r;                                                             // eax = the wait's 0
    }
    ImpP_t leave = c3fe_imp<ImpP_t>(kIatLeaveCS);                             // 0x1002a9a5
    Peek_t peek = c3fe_imp<Peek_t>(kIatPeekMessageA);                         // 0x1002a9ab
    for (;;) {
        c3fe_imp<ImpP_t>(kIatEnterCS)(cs);                                    // 0x1002a9b1 / 0x1002a9b6
        if (!(c3fe_g<unsigned char>(kSigObj) & 1)) {                          // 0x1002a9bc / 0x1002a9c3
            unsigned e = leave(cs);                                           // 0x1002aa2d / 0x1002aa32
            c3fe_g<unsigned char>(kSigRunning) = 0;                           // 0x1002aa36
            return NEG_ON ? 0 : e;                                            // NEGCTL
        }
        c3fe_msg m;
        while (peek(&m, 0, 0, 0, 1)) {                                        // 0x1002a9c5-0x1002a9d6 / 0x1002a9f4-0x1002aa05
            c3fe_fn<Cdecl4_t>(0x00001780)(m.hwnd, m.message, m.wParam, m.lParam);   // 0x1002a9d8-0x1002a9f1
        }
        leave(cs);                                                            // 0x1002aa07 / 0x1002aa0c
        r = wait(1, ev, 0, 0xffffffffu, 0x48);                                // 0x1002aa0e-0x1002aa1b
        if (r == 0) {                                                         // 0x1002aa1d / 0x1002aa1f
            c3fe_g<unsigned char>(kSigRunning) = static_cast<unsigned char>(r);   // 0x1002aa23
            return r;
        }
    }
}

